sections.css:
.ps-page {
  position: relative;
  min-height: 100vh;
  padding-top: 178px;
  padding-bottom: 80px;
  background-color: var(--color-bg);
  background-image: var(--ps-bg-image, none);
  background-repeat: no-repeat;
  background-size: cover;
  background-position: top;
}

:root[data-theme="light"] .ps-page {
  background-image: var(--ps-bg-image-light, none);
}

.ps-page__container {
  max-width: 744px;
  margin-inline: auto;
}

.ps-page__title,
.ps-page__subtitle {
  text-align: center;
}

.ps-page__body {
  margin-top: 60px;
}

.ps {
  --ps-ring: linear-gradient(249.99deg, #fff0 4.98%, #6bedf9 37.35%, #ffa72c 72.51%, #fff0 96.41%);
  --ps-ring-hover: linear-gradient(264.85deg, #fff0 -6.54%, #ffa72c 24.73%, #6bedf9 70.73%, #fff0 113.1%);
  --ps-accent: var(--color-cyan);
  --ps-muted: rgb(255 255 255 / 0.62);
  --ps-soft: rgb(255 255 255 / 0.08);
  --ps-line: rgb(255 255 255 / 0.1);
  --ps-selected-bg: rgb(107 234 249 / 0.06);
}

:root[data-theme="light"] .ps {
  --ps-accent: var(--color-blue);
  --ps-muted: rgb(0 0 0 / 0.58);
  --ps-soft: rgb(0 0 0 / 0.05);
  --ps-line: rgb(0 0 0 / 0.1);
  --ps-selected-bg: rgb(79 149 255 / 0.06);
}

.ps [hidden] {
  display: none !important;
}

.ps-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.ps-icon {
  width: 1.25rem;
  height: 1.25rem;
  flex-shrink: 0;
}

.ps :focus-visible {
  outline: 2px solid var(--ps-accent);
  outline-offset: 3px;
}

.ps .df-input:focus-visible {
  outline: none;
}

.ps-step-title:focus,
.ps-status__title:focus,
.ps-order__title:focus {
  outline: none;
}

.ps-step-title {
  margin-bottom: 1.5rem;
}

.ps-step {
  animation: df-in 0.4s ease both;
}

.ps-hint {
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--ps-muted);
  padding-inline-start: 0.25rem;
}

.ps-optional {
  color: var(--ps-muted);
  font-size: 0.875em;
}

.ps-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 1rem;
}

.ps-link {
  color: var(--ps-accent);
  font-weight: 500;
}

.ps-link:hover {
  text-decoration: underline;
}

.ps-link--forward::after {
  content: "\00a0→";
}

[dir="rtl"] .ps-link--forward::after {
  content: "\00a0←";
}

.ps-ring,
.ps-plan,
.ps-addon,
.ps-period,
.ps-order {
  position: relative;
  isolation: isolate;
}

.ps-plan::before,
.ps-plan::after,
.ps-period::before,
.ps-order::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  z-index: 1;
  opacity: 0;
  transition: opacity 0.25s ease;
}

.ps-plan::before {
  background: var(--ps-ring);
}

.ps-plan::after {
  background: var(--ps-ring-hover);
  padding: 2px;
}

.ps-period::before,
.ps-order::before {
  background: var(--color-dark-gray-stroke);
  opacity: 1;
}

:root[data-theme="light"] .ps-period::before,
:root[data-theme="light"] .ps-order::before {
  background: var(--color-light-gray-stroke);
}

.ps-period {
  display: inline-flex;
  gap: 0.25rem;
  padding: 0.3125rem;
  border-radius: var(--border-radius);
  background: var(--df-field-bg);
  align-self: flex-start;
}

.ps-period__option {
  position: relative;
  display: inline-flex;
}

.ps-period__input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
  cursor: pointer;
}

.ps-period__text {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding: 0 1.375rem;
  border-radius: var(--border-radius);
  font-size: 1rem;
  font-weight: 500;
  color: var(--ps-muted);
  transition: color 0.2s ease, background-color 0.2s ease;
}

.ps-period__input:checked + .ps-period__text {
  color: var(--color-heading);
  background: rgb(255 255 255 / 0.1);
  box-shadow: inset 0 0 0 1px rgb(107 234 249 / 0.45);
}

:root[data-theme="light"] .ps-period__input:checked + .ps-period__text {
  background: var(--color-white);
  box-shadow: inset 0 0 0 1px rgb(79 149 255 / 0.5), 0 2px 8px rgb(0 0 0 / 0.06);
}

.ps-period__input:focus-visible + .ps-period__text {
  outline: 2px solid var(--ps-accent);
  outline-offset: 2px;
}

.ps-plans {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.ps-plan {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: start;
  gap: 1rem;
  padding: 1.375rem 1.5rem;
  border-radius: var(--df-radius);
  background: var(--df-field-bg);
  cursor: pointer;
  transition: background-color 0.25s ease;
}

.ps-plan:hover::before {
  opacity: 1;
}

.ps-plan--selected {
  background: var(--ps-selected-bg);
}

.ps-plan--selected::after {
  opacity: 1;
}

.ps-plan--selected:hover::before {
  opacity: 0;
}

.ps-plan:has(.df-choice-input:focus-visible) {
  outline: 2px solid var(--ps-accent);
  outline-offset: 3px;
}

.ps-plan .df-choice-custom {
  margin-top: 0.1875rem;
}

.ps-plan__body {
  display: flex;
  flex-direction: column;
  gap: 0.3125rem;
  min-width: 0;
}

.ps-plan__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.75rem;
}

.ps-plan__name {
  font-size: 1.375rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-heading);
}

.ps-plan__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.625rem;
  border-radius: var(--border-radius);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ps-accent);
  box-shadow: inset 0 0 0 1px currentColor;
}

.ps-plan__kicker {
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ps-accent);
}

.ps-plan__desc {
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--ps-muted);
}

.ps-plan__meta {
  margin-top: 0.25rem;
  font-size: 0.875rem;
  color: var(--color-heading);
  opacity: 0.85;
}

.ps-plan__price {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  text-align: end;
  gap: 0.125rem;
  white-space: nowrap;
}

.ps-plan__amount {
  font-size: 1.75rem;
  font-weight: 600;
  line-height: 1.1;
  color: var(--color-heading);
  letter-spacing: -0.02em;
}

.ps-plan__period {
  font-size: 0.875rem;
  color: var(--ps-muted);
}

.ps-plan--sales {
  grid-template-columns: 1fr auto;
  cursor: default;
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--ps-line);
  padding-inline-start: calc(1.5rem + 1.25rem + 1rem);
}

.ps-plan--sales::before,
.ps-plan--sales::after {
  display: none;
}

.ps-plan__price--sales {
  gap: 0.375rem;
}

.ps-plan__custom {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-heading);
}

.ps-addon {
  display: flex;
  flex-direction: column;
  gap: 1.125rem;
  padding: 1.5rem;
  margin-bottom: 1rem;
  border-radius: var(--df-radius);
  background: var(--df-field-bg);
  box-shadow: inset 0 0 0 1px var(--ps-line);
}

.ps-addon__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.ps-addon__title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.25;
  color: var(--color-heading);
}

.ps-addon__meta {
  margin: 0.375rem 0 0;
  font-size: 0.9375rem;
  line-height: 1.45;
  color: var(--ps-muted);
}

.ps-qty {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  flex-shrink: 0;
}

.ps-qty__btn {
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  border: 1px solid rgb(255 255 255 / 0.22);
  background: transparent;
  color: var(--color-heading);
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

.ps-qty__btn:hover:not(:disabled) {
  border-color: var(--ps-accent);
  background: var(--ps-selected-bg);
}

.ps-qty__btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

:root[data-theme="light"] .ps-qty__btn {
  border-color: rgb(0 0 0 / 0.18);
}

.ps-qty__value {
  width: 3.5rem;
  height: 2.75rem;
  border: none;
  border-radius: 0.75rem;
  background: var(--ps-soft);
  color: var(--color-heading);
  font: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: center;
}

.ps-capacity {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.ps-capacity__bar {
  height: 0.375rem;
  border-radius: var(--border-radius);
  background: var(--ps-soft);
  overflow: hidden;
}

.ps-capacity__fill {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, #6bedf9 0%, #ffa72c 100%);
}

[dir="rtl"] .ps-capacity__fill {
  background: linear-gradient(270deg, #6bedf9 0%, #ffa72c 100%);
  transition: width 0.3s ease;
}

.ps-capacity__text {
  margin: 0;
  font-size: 0.9375rem;
  color: var(--color-heading);
}

.ps-capacity__note {
  padding-inline-start: 0;
}

.ps-capacity__note--limit {
  color: #ffa72c;
}

:root[data-theme="light"] .ps-capacity__note--limit {
  color: #b66a00;
}

.ps-toggle {
  align-self: flex-start;
  padding: 0;
  font-weight: 500;
}

.ps-toggle:hover {
  background: transparent;
}

.ps-addon .df-field {
  margin-bottom: 0;
}

.ps-note {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  margin: 0;
  padding: 0.75rem 1rem;
  border-radius: 0.875rem;
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--color-heading);
  background: rgb(255 167 44 / 0.1);
  box-shadow: inset 0 0 0 1px rgb(255 167 44 / 0.28);
}

.ps-note .ps-icon {
  color: #ffa72c;
  margin-top: 0.0625rem;
}

:root[data-theme="light"] .ps-note .ps-icon {
  color: #b66a00;
}

.ps-empty {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 1.5rem;
  border-radius: var(--df-radius);
  color: var(--ps-muted);
  box-shadow: inset 0 0 0 1px var(--ps-line);
}

.ps-empty p {
  margin: 0;
  line-height: 1.5;
}

.ps-nav {
  margin-top: 2rem;
}

.ps-btn-link {
  text-decoration: none;
}

.ps-banner {
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--df-radius);
  background: rgb(255 108 86 / 0.08);
  box-shadow: inset 0 0 0 1px rgb(255 108 86 / 0.3);
  color: var(--color-heading);
  font-size: 0.9375rem;
  line-height: 1.45;
}

.ps-banner .ps-icon {
  color: var(--color-red);
  margin-top: 0.125rem;
}

.ps-banner strong {
  display: block;
  font-weight: 600;
}

.ps-banner p {
  margin: 0.25rem 0 0;
  color: var(--ps-muted);
}

.ps-status {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
  padding: 1rem 0 0.5rem;
  animation: df-in 0.4s ease both;
}

.ps-status__icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 4.5rem;
  height: 4.5rem;
  border-radius: 50%;
  color: var(--color-heading);
  background: var(--df-field-bg);
}

.ps-status__icon::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 2px;
  background: var(--ps-ring);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.ps-status__icon .ps-icon {
  width: 1.875rem;
  height: 1.875rem;
}

.ps-status--success .ps-status__icon {
  color: var(--ps-accent);
}

.ps-status--error .ps-status__icon {
  color: var(--color-red);
}

.ps-status--error .ps-status__icon::before {
  background: linear-gradient(180deg, rgb(255 108 86 / 0.7), rgb(255 108 86 / 0.15));
}

.ps-status__title {
  margin: 0.25rem 0 0;
  font-size: 1.75rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-heading);
}

.ps-status__body {
  margin: 0;
  max-width: 34rem;
  font-size: 1.0625rem;
  line-height: 1.55;
  color: var(--ps-muted);
}

.ps-email {
  color: var(--color-heading);
  font-weight: 600;
  word-break: break-all;
}

.ps-status__hint {
  margin: 0;
  max-width: 30rem;
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--ps-muted);
}

.ps-status__actions {
  width: 100%;
  margin-top: 0.5rem;
}

.ps-timeline {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  width: 100%;
  max-width: 30rem;
  margin: 0.75rem 0 0;
  padding: 0;
  list-style: none;
  text-align: start;
}

.ps-timeline__item {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border-radius: 1rem;
  background: var(--df-field-bg);
  color: var(--color-heading);
  font-size: 0.9375rem;
  line-height: 1.4;
}

.ps-timeline__num {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  border: 1px solid rgb(255 255 255 / 0.2);
  font-size: 0.8125rem;
  font-weight: 500;
  color: rgb(255 255 255 / 0.5);
}

.ps-timeline__item--current .ps-timeline__num {
  border-color: var(--ps-accent);
  color: var(--ps-accent);
}

:root[data-theme="light"] .ps-timeline__num {
  border-color: rgb(0 0 0 / 0.15);
  color: rgb(0 0 0 / 0.45);
}

:root[data-theme="light"] .ps-timeline__item--current .ps-timeline__num {
  border-color: var(--ps-accent);
  color: var(--ps-accent);
}

.ps-order {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  padding: 2rem;
  border-radius: var(--df-radius);
  background: var(--df-field-bg);
  animation: df-in 0.4s ease both;
}

.ps-order__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.ps-order__number {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ps-accent);
}

.ps-order__title {
  margin: 0.375rem 0 0;
  font-size: 1.625rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-heading);
}

.ps-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.875rem;
  border-radius: var(--border-radius);
  font-size: 0.8125rem;
  font-weight: 600;
  white-space: nowrap;
  color: var(--color-heading);
  box-shadow: inset 0 0 0 1px var(--ps-line);
}

.ps-chip::before {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: currentColor;
}

.ps-chip--draft {
  color: #ffa72c;
  box-shadow: inset 0 0 0 1px rgb(255 167 44 / 0.4);
}

:root[data-theme="light"] .ps-chip--draft {
  color: #b66a00;
}

.ps-order__columns,
.ps-order__line {
  display: grid;
  grid-template-columns: 1fr 4.5rem 8rem;
  gap: 1rem;
  align-items: baseline;
}

.ps-order__columns {
  padding-bottom: 0.625rem;
  border-bottom: 1px solid var(--ps-line);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ps-muted);
}

.ps-order__columns span:nth-child(n + 2),
.ps-order__qty,
.ps-order__amount {
  text-align: end;
}

.ps-order__lines {
  display: flex;
  flex-direction: column;
  margin: -0.5rem 0 0;
  padding: 0;
  list-style: none;
}

.ps-order__line {
  padding: 0.875rem 0;
  border-bottom: 1px solid var(--ps-line);
}

.ps-order__item {
  display: flex;
  flex-direction: column;
  gap: 0.1875rem;
  min-width: 0;
}

.ps-order__name {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-heading);
}

.ps-order__unit {
  font-size: 0.8125rem;
  color: var(--ps-muted);
}

.ps-order__qty {
  color: var(--ps-muted);
  font-variant-numeric: tabular-nums;
}

.ps-order__amount {
  font-weight: 500;
  color: var(--color-heading);
  font-variant-numeric: tabular-nums;
}

.ps-order__totals {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
  margin-inline-start: auto;
  width: min(100%, 22rem);
}

.ps-order__total-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.9375rem;
  color: var(--ps-muted);
}

.ps-order__total-row dt,
.ps-order__total-row dd {
  margin: 0;
}

.ps-order__total-row dd {
  color: var(--color-heading);
  font-variant-numeric: tabular-nums;
  text-align: end;
}

.ps-order__total-row--grand {
  padding-top: 0.75rem;
  border-top: 1px solid var(--ps-line);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-heading);
}

.ps-order__total-row--grand dd {
  font-size: 1.375rem;
}

.ps-order__pending {
  color: var(--ps-muted) !important;
  font-size: 0.875rem !important;
  font-weight: 400;
}

.ps-order__expires {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  font-size: 0.8125rem;
  color: var(--ps-muted);
}

.ps-order__expires .ps-icon {
  width: 1rem;
  height: 1rem;
}

.ps-order .ps-banner {
  margin-top: 0;
}

@media (width < 120rem) {
  .ps-page {
    padding-top: 175px;
  }
}

@media (width < 90rem) {
  .ps-page {
    padding-top: 160px;
  }
}

@media (width < 64rem) {
  .ps-page {
    padding-top: 150px;
  }
}

@media (width < 48rem) {
  .ps-page {
    padding-top: 128px;
    padding-bottom: 48px;
    background-image: var(--ps-bg-image-mobile, var(--ps-bg-image, none));
  }

  .ps-page__body {
    margin-top: 36px;
  }

  .ps-row {
    grid-template-columns: 1fr;
  }

  .ps-period {
    align-self: stretch;
  }

  .ps-period__option {
    flex: 1;
  }

  .ps-period__text {
    justify-content: center;
    width: 100%;
    padding: 0 1rem;
  }

  .ps-plan {
    grid-template-columns: auto 1fr;
    gap: 0.75rem 0.875rem;
    padding: 1.125rem 1.125rem;
  }

  .ps-plan__price {
    grid-column: 2;
    flex-direction: row;
    align-items: baseline;
    gap: 0.375rem;
  }

  .ps-plan__amount {
    font-size: 1.5rem;
  }

  .ps-plan__name {
    font-size: 1.1875rem;
  }

  .ps-plan--sales {
    grid-template-columns: 1fr;
    padding-inline-start: 1.125rem;
  }

  .ps-plan--sales .ps-plan__price {
    grid-column: 1;
    flex-direction: column;
    align-items: flex-start;
    text-align: start;
  }

  .ps-addon {
    padding: 1.125rem;
  }

  .ps-addon__head {
    flex-direction: column;
  }

  .ps-status__title {
    font-size: 1.375rem;
  }

  .ps-status__body {
    font-size: 0.9375rem;
  }

  .ps-order {
    padding: 1.25rem;
  }

  .ps-order__head {
    flex-direction: column-reverse;
    gap: 0.75rem;
  }

  .ps-order__title {
    font-size: 1.3125rem;
  }

  .ps-order__columns {
    display: none;
  }

  .ps-order__line {
    grid-template-columns: 1fr auto;
    gap: 0.25rem 1rem;
  }

  .ps-order__qty {
    grid-column: 1;
    grid-row: 2;
    text-align: start;
    font-size: 0.8125rem;
  }

  .ps-order__amount {
    grid-column: 2;
    grid-row: 1 / span 2;
    align-self: center;
  }
}

